mapper.select:
WITH candidates AS ( SELECT c.id AS card_id, GREATEST(c.updated_at,COALESCE(g.updated_at,c.updated_at),COALESCE(s.updated_at,c.updated_at)) AS sort_time FROM memory_card c LEFT JOIN memory_review_gate g ON g.owner_id=c.owner_id AND g.card_id=c.id LEFT JOIN memory_schedule s ON s.owner_id=c.owner_id AND s.card_id=c.id LEFT JOIN memory_active_attempt a ON a.owner_id=c.owner_id AND a.card_id=c.id WHERE c.owner_id=#{owner} AND c.status='ACTIVE' AND a.attempt_id IS NULL ) SELECT card_id,sort_time FROM candidates
WHERE (sort_time < #{cursor.time} OR (sort_time=#{cursor.time} AND card_id > #{cursor.cardId}))
ORDER BY sort_time DESC,card_id ASC LIMIT #{limit}

mapper.sql:
WITH schedules AS (
  SELECT c.id AS card_id,GREATEST(s.suggested_due_at,COALESCE(s.defer_until,s.suggested_due_at)) AS sort_time
  FROM memory_schedule s
  JOIN memory_card c ON c.owner_id=s.owner_id AND c.id=s.card_id
  JOIN memory_card_version v ON v.owner_id=c.owner_id AND v.card_id=c.id AND v.id=c.current_version_id
  WHERE s.owner_id=#{owner} AND c.status='ACTIVE' AND s.status IN ('ACTIVE','PAUSED')
), candidates AS (
  SELECT card_id,sort_time FROM schedules WHERE sort_time >= #{from} AND sort_time < #{until}
)

mapper.select:

SELECT card_id,sort_time FROM candidates

  WHERE (sort_time > #{cursor.time} OR (sort_time=#{cursor.time} AND card_id > #{cursor.cardId}))

ORDER BY sort_time ASC,card_id ASC LIMIT #{limit}

WITH candidates AS (
  SELECT a.card_id,COALESCE(p.order_value,500000) AS order_value,a.started_at AS sort_time,a.id AS final_id
  FROM memory_active_attempt s
  JOIN memory_recall_attempt a ON a.owner_id=s.owner_id AND a.card_id=s.card_id AND a.id=s.attempt_id

  LEFT JOIN today_placement p ON p.owner_id=a.owner_id AND p.source_kind='MEMORY_CARD' AND p.source_id=a.card_id
  WHERE s.owner_id=#{owner} AND a.started_at <= #{asOf}
)
SELECT card_id,order_value,NULL AS phase_rank,sort_time,final_id FROM candidates

  WHERE (order_value > #{after.orderValue}
    OR (order_value=#{after.orderValue} AND sort_time < #{after.time})
    OR (order_value=#{after.orderValue} AND sort_time=#{after.time} AND final_id < #{after.id}))

ORDER BY order_value ASC,sort_time DESC,final_id DESC LIMIT #{limit}

WITH candidates AS ( SELECT c.id AS card_id,COALESCE(p.order_value,500000) AS order_value, GREATEST(c.updated_at,COALESCE(g.updated_at,c.updated_at),COALESCE(s.updated_at,c.updated_at)) AS sort_time FROM memory_card c LEFT JOIN memory_review_gate g ON g.owner_id=c.owner_id AND g.card_id=c.id LEFT JOIN memory_schedule s ON s.owner_id=c.owner_id AND s.card_id=c.id LEFT JOIN memory_active_attempt a ON a.owner_id=c.owner_id AND a.card_id=c.id LEFT JOIN today_placement p ON p.owner_id=c.owner_id AND p.source_kind='MEMORY_CARD' AND p.source_id=c.id WHERE c.owner_id=#{owner} AND c.status='ACTIVE' AND a.attempt_id IS NULL ) SELECT card_id,order_value,NULL AS phase_rank,sort_time,card_id AS final_id FROM candidates
WHERE (order_value > #{after.orderValue} OR (order_value=#{after.orderValue} AND sort_time < #{after.time}) OR (order_value=#{after.orderValue} AND sort_time=#{after.time} AND card_id > #{after.id}))
ORDER BY order_value ASC,sort_time DESC,card_id ASC LIMIT #{limit}

, placed AS (
  SELECT c.card_id,c.sort_time,COALESCE(p.order_value,500000) AS order_value FROM candidates c
  LEFT JOIN today_placement p ON p.owner_id=#{owner} AND p.source_kind='MEMORY_CARD' AND p.source_id=c.card_id
)
SELECT card_id,order_value,NULL AS phase_rank,sort_time,card_id AS final_id FROM placed

  WHERE (sort_time > #{after.time}
    OR (sort_time=#{after.time} AND order_value > #{after.orderValue})
    OR (sort_time=#{after.time} AND order_value=#{after.orderValue} AND card_id > #{after.id}))

ORDER BY sort_time ASC,order_value ASC,card_id ASC LIMIT #{limit}

, queue_values AS (

), placed AS (
  SELECT q.*,r.phase_rank,COALESCE(p.order_value,500000) AS order_value FROM queue_values q
  JOIN recommendations r ON r.card_id=q.card_id
  LEFT JOIN today_placement p ON p.owner_id=#{owner} AND p.source_kind='MEMORY_CARD' AND p.source_id=q.card_id
  WHERE q.recommended=1
)
SELECT card_id,kind,title,card_version_id,card_version_number,card_revision,gate_revision,schedule_revision,cycle_id,
  phase,effective_due_at,budget_kind,counted_today,recommended,requires_budget_confirmation,archived_concept,
  order_value,phase_rank FROM placed

  WHERE (order_value > #{after.orderValue}
    OR (order_value=#{after.orderValue} AND phase_rank > #{after.phaseRank})
    OR (order_value=#{after.orderValue} AND phase_rank=#{after.phaseRank} AND effective_due_at > #{after.time})
    OR (order_value=#{after.orderValue} AND phase_rank=#{after.phaseRank}
      AND effective_due_at=#{after.time} AND card_id > #{after.id}))

ORDER BY order_value ASC,phase_rank ASC,effective_due_at ASC,card_id ASC LIMIT #{limit}
